const MAX_SAFE = Number.MAX_SAFE_INTEGER;

export function quote(lines, discountPercent = 0) {
  if (!Array.isArray(lines)) throw new TypeError("lines must be an array");
  if (!Number.isInteger(discountPercent) || discountPercent < 0 || discountPercent > 100) {
    throw new RangeError("discountPercent must be an integer from 0 to 100");
  }

  let subtotalCents = 0;
  for (const line of lines) {
    if (line === null || typeof line !== "object" || Array.isArray(line)) {
      throw new TypeError("each line must be an object");
    }
    const keys = Reflect.ownKeys(line);
    if (keys.length !== 2 || !keys.includes("unitCents") || !keys.includes("quantity")) {
      throw new TypeError("each line must have exactly unitCents and quantity");
    }

    const {unitCents, quantity} = line;
    if (!Number.isSafeInteger(unitCents) || unitCents < 0) {
      throw new RangeError("unitCents must be a nonnegative safe integer");
    }
    if (!Number.isSafeInteger(quantity) || quantity <= 0) {
      throw new RangeError("quantity must be a positive safe integer");
    }

    const lineTotal = unitCents * quantity;
    if (!Number.isSafeInteger(lineTotal) || subtotalCents > MAX_SAFE - lineTotal) {
      throw new RangeError("quote subtotal exceeds the safe integer range");
    }
    subtotalCents += lineTotal;
  }

  const discountCents = Number(BigInt(subtotalCents) * BigInt(discountPercent) / 100n);
  const totalCents = subtotalCents - discountCents;
  return {version: 2, subtotalCents, discountCents, totalCents, total: totalCents};
}

