import json,sys
sys.path.insert(0,'/home/dev/probe')
from stock.allocation import reserve,release
def attempt(name,fn,expected=None,raises=False):
    try:
        result=fn()
        return dict(name=name,passed=not raises and result==expected,result=result)
    except Exception as error:
        return dict(name=name,passed=raises and isinstance(error,ValueError),error=type(error).__name__+': '+str(error))
cases=[
attempt('reserve empty inventory',lambda:reserve({},[]),dict(remaining={},reserved={})),
attempt('release empty inventories',lambda:release({},{},[]),dict(remaining={},held={})),
attempt('invalid stock with nonempty valid request',lambda:reserve({'a':'bad'},[{'sku':'a','quantity':1}]),raises=True),
attempt('invalid held with nonempty valid return',lambda:release({'a':0},{'a':'bad'},[{'sku':'a','quantity':1}]),raises=True)]
print(json.dumps(dict(cases=cases,passed=all(c['passed'] for c in cases))))

